<?php $module='products';$title='Product reviews';$description='Approve genuine purchase experiences before they appear on the website.';require __DIR__.'/header.php'; ?>
<?php if(!$reviews): ?><section class="panel"><h2>No pending reviews</h2><p>New and edited customer reviews will appear here for moderation.</p></section><?php endif; ?>
<?php foreach($reviews as $review): ?><section class="panel"><h2><?= $e($review['product_name']) ?></h2><p><strong><?= $e($review['rating']) ?> ★ · <?= $e($review['title']) ?></strong></p><p><?= $e($review['body']) ?></p><small>Review #<?= $e($review['id']) ?> · Revision <?= $e($review['revision']) ?></small><?php if($can('admin.products.edit')): ?><form method="post" action="<?= $u('admin/product-reviews') ?>"><?php $hidden(['csrf'=>$csrf,'id'=>$review['id'],'revision'=>$review['revision'],'operation_key'=>$key()]); ?><div class="actions"><button name="status" value="approved" class="button">Approve</button><button name="status" value="rejected" class="button secondary">Reject</button></div></form><?php endif; ?></section><?php endforeach; ?>
<div class="actions"><?php if($page>1): ?><a href="?page=<?= $page-1 ?>" class="button secondary">Previous</a><?php endif; ?><?php if(count($reviews)===20): ?><a href="?page=<?= $page+1 ?>" class="button secondary">Next</a><?php endif; ?></div>
<?php require __DIR__.'/footer.php'; ?>
